  def current do
    case Agentboard.Repo.statement(
           "SELECT version FROM board_schema WHERE id = 1 AND to_regclass('archive_policy') IS NOT NULL AND to_regclass('task_archives') IS NOT NULL AND to_regclass('oban_jobs') IS NOT NULL AND to_regclass('context_entries') IS NOT NULL AND to_regclass('context_links') IS NOT NULL AND to_regclass('context_receipts') IS NOT NULL AND to_regclass('board_action_events') IS NOT NULL AND to_regclass('tasks_versions') IS NOT NULL AND to_regclass('delivery_pull_requests') IS NOT NULL AND to_regclass('delivery_task_links') IS NOT NULL AND to_regclass('delivery_poll_states') IS NOT NULL AND to_regclass('delivery_poll_states_versions') IS NOT NULL AND to_regclass('delivery_poll_credits') IS NOT NULL AND to_regclass('delivery_provider_budgets') IS NOT NULL AND to_regclass('delivery_ci_snapshots') IS NOT NULL AND to_regclass('cooperation_receipts') IS NOT NULL AND to_regclass('delivery_obligations') IS NOT NULL AND to_regclass('conversation_coverage') IS NOT NULL AND to_regclass('availability_policies') IS NOT NULL AND to_regclass('decision_requests') IS NOT NULL AND to_regclass('decision_wakes') IS NOT NULL AND to_regclass('delivery_base_watches') IS NOT NULL AND to_regclass('delivery_rebase_follow_ups') IS NOT NULL AND to_regclass('mattermost_agent_bots') IS NOT NULL AND to_regclass('mattermost_inbox') IS NOT NULL AND to_regclass('mattermost_post_versions') IS NOT NULL AND to_regclass('mattermost_channel_recovery') IS NOT NULL AND to_regclass('mattermost_inbound_runs') IS NOT NULL AND to_regclass('delivery_duplicate_findings') IS NOT NULL AND to_regclass('agent_api_credentials') IS NOT NULL AND to_regclass('agent_auth_observations') IS NOT NULL AND to_regclass('delivery_workflow_runs') IS NOT NULL AND to_regclass('delivery_workflow_health') IS NOT NULL AND to_regclass('recovery_episodes') IS NOT NULL AND to_regclass('recovery_attempts') IS NOT NULL AND to_regclass('recovery_episodes_versions') IS NOT NULL AND to_regclass('recovery_attempts_versions') IS NOT NULL AND to_regclass('wake_intents') IS NOT NULL AND to_regclass('wake_attempts') IS NOT NULL AND to_regclass('wake_intents_versions') IS NOT NULL AND to_regclass('wake_attempts_versions') IS NOT NULL AND to_regclass('seat_scopes') IS NOT NULL AND to_regclass('seat_scopes_versions') IS NOT NULL AND to_regclass('fleet_loadouts') IS NOT NULL AND to_regclass('fleet_seat_bindings') IS NOT NULL AND to_regclass('fleet_loadout_receipts') IS NOT NULL AND to_regclass('fleet_loadouts_versions') IS NOT NULL AND to_regclass('coordinator_triage_configuration') IS NOT NULL AND to_regclass('coordinator_triage_configuration_versions') IS NOT NULL AND to_regclass('coordinator_inbox_triage') IS NOT NULL AND to_regclass('coordinator_triage_dispositions') IS NOT NULL AND to_regclass('branch_flow_configuration') IS NOT NULL AND to_regclass('branch_flow_configuration_versions') IS NOT NULL AND to_regclass('branch_flow_receipts') IS NOT NULL AND to_regclass('delivery_conflict_orders') IS NOT NULL AND to_regclass('delivery_conflict_orders_versions') IS NOT NULL AND to_regclass('delivery_publication_grants') IS NOT NULL AND to_regclass('delivery_publication_grants_versions') IS NOT NULL AND to_regclass('delivery_publication_bindings') IS NOT NULL AND to_regclass('delivery_publication_bindings_versions') IS NOT NULL AND to_regclass('delivery_conflict_sources') IS NOT NULL AND to_regclass('delivery_repository_metadata') IS NOT NULL AND to_regclass('coordinator_handling_batches') IS NOT NULL AND to_regclass('coordinator_handling_items') IS NOT NULL",
